    textMat: textMat, contextMat: contextMat, readabilityMat: readabilityMat, glowMat: glowMat, sparkMat: pmat, sunMat: sunMat,
    rowLayerGroup: rowLayerGroup,
    rowLayers: rowLayerBundle ? rowLayerBundle.rows : null,
